import json, numpy as np
path='/home/USER/runs/paper/glm-ha-u1-turns/frozen/seen-3/play/users/u059/system/state/sessions/01a1a13e-c276-759f-9ca9-804a1b92ee76.jsonl'
grids=[]
with open(path) as f:
    for line in f:
        if '"submit"' not in line: continue
        obj=json.loads(line)
        msg=obj.get('message',{})
        for c_ in msg.get('content',[]):
            if c_.get('type')=='text':
                try:
                    a_=json.loads(c_['text'])
                    if a_.get('action')=='submit':
                        grids.append(np.array(a_['grid']))
                except Exception as e:
                    pass
print(len(grids))
T=np.array(T)
for i,g_ in enumerate(grids):
    g_=np.array(g_)
    if g_.shape!=T.shape:
        print(i,'shape',g_.shape); continue
    d=np.argwhere(g_!=T)
    print(i, 'diff cells:', [tuple(x) for x in d])

